// m68k_alu_rowdec.sv - row decoder of the ALU matrix (FIG. 18) as an exhaustive table on ird[15:3] (ird[2:0] is not an input).
// GENERATED by gen_rowdec_case.py from docs/data/mc68000_alu_rowdec_dump.txt, the dump of the 45-term module of gen_alu_rowdec.py: same function by construction.
// Outputs: row = row 1..15 (0 = none), cc_inh = An destination (PSW not updated), row_n = negated one-hot (not used in the core).
module m68k_alu_rowdec (
  /* verilator lint_off UNUSEDSIGNAL */
  input  logic [15:0] ird,
  /* verilator lint_on UNUSEDSIGNAL */
  output logic [14:0] row_n,
  output logic [3:0]  row,
  output logic        cc_inh
